__mods['fangchan_game'] = function()
-- 买房记：玩法规则和状态。
--
-- 这一层是纯逻辑，不认识屏幕：ui.lua 调它的方法、读它的字段。一回合里值得告诉玩家的事，
-- 方法会往一个 messages 表里塞短句，界面负责显示。
--
-- 一局的流程：开局 2000 元、60 个回合。每回合先让所有商品随机涨跌（围着基准价漂），再抽
-- 一条新闻；玩家在这回合里想买多少就买多少，点"下一回合"进入下一回合。仓库不限量，
-- 钱够就能买房，60 回合里买到房就算赢。另外每回合可以买几张刮刮乐碰碰运气。

local Data = require('fangchan_data')
local T = require('ffi/util').template

local Game = {}
Game.__index = Game

Game.MAX_ROUNDS = Data.MAX_ROUNDS

-- 12345 -> "12,345"
local function formatNumber(n)
  n = math.floor(tonumber(n) or 0)
  local sign = ''
  if n < 0 then sign = '-'; n = -n end
  local s = tostring(n)
  local out = s:reverse():gsub('(%d%d%d)', '%1,'):reverse()
  return sign .. (out:gsub('^,', ''))
end

function Game.format(n) return formatNumber(n) end
function Game:money(n) return T(Data.money_fmt, formatNumber(n)) end

function Game:new()
  local g = setmetatable({}, self)
  g:newGame()
  return g
end

function Game:newGame()
  math.randomseed(os.time())
  self.round = 1
  self.cash = Data.START_CASH
  self.owned = 0                 -- 0 = 还没房；否则是 Data.HOUSES 的下标
  self.over = false
  self.inventory, self.prices, self.prev, self.log, self.basis = {}, {}, {}, {}, {}
  for i, good in ipairs(Data.GOODS) do
    self.inventory[i] = 0
    self.basis[i] = 0            -- 手上这批货的平均买入价，卖出时给玩家对照
    -- 开局的价格不直接等于基准价，先随机偏一点
    self.prices[i] = math.max(1, math.floor(good.base * (0.8 + math.random() * 0.4)))
    self.prev[i] = self.prices[i]
  end
  self.lotto_left = Data.LOTTERY.per_round   -- 这一回合还能买几张
  self.lotto_free = 0                        -- 白得的彩票券，随时能兑，不占名额
  self.lotto_n, self.lotto_spent, self.lotto_win = 0, 0, 0
  self.lotto_cells, self.lotto_open = nil, nil   -- 手上那张卡：六个格子的奖品、刮开了哪几格
  self.lotto_pool = Data.LOTTERY.pool_start  -- 本期奖池：每张票往里注钱，1/150 的机会独得
  self:resetTip()                        -- 上一条小道消息：这一回合买，下一回合看它应不应验
  self.tip_left = Data.TIPS.per_round    -- 这回合还能买几条消息
  self.stat = self:newStat()             -- 这一局的账，成就勋章看它
  self.log[1] = T('开局：%1 的启动资金，%2 个回合，赚够钱买一套房。', self:money(Data.START_CASH), Data.MAX_ROUNDS)
  return self
end

------------------------------------------------------------------ 这一局的账（成就看它）

-- 只记本局的事：成就里"一局内如何如何"的看这里。跨局累加的那些在界面那边（best.txt）
function Game:newStat()
  return { best_trade = 0, max_hold = 0, house_buys = 0, first_round = 0,
    max_net = 0, traded = 0, tips = 0, max_cell = 0, blank_cards = 0, pool_wins = 0 }
end

-- 交易过第 i 种货，记一笔（成就"八面玲珑"要数这个）
local function mark_traded(self, i)
  if not self.stat then self.stat = self:newStat() end
  if i and i >= 1 and i <= 8 then self.stat.traded = (self.stat.traded or 0) | (1 << (i - 1)) end
end
function Game:tradedCount()
  if not self.stat then return 0 end
  local n = self.stat.traded or 0
  local c = 0
  for i = 1, #Data.GOODS do if n & (1 << (i - 1)) ~= 0 then c = c + 1 end end
  return c
end

-- 每回合结束、每笔买卖之后都该走一遍：把这一刻的数字记进账里
function Game:tally()
  if not self.stat then self.stat = self:newStat() end
  local s = self.stat
  local h = self:held()
  if h > (s.max_hold or 0) then s.max_hold = h end
  local nw = self:netWorth()
  if nw > (s.max_net or 0) then s.max_net = nw end
  return s
end

------------------------------------------------------------------ 小道消息

function Game:resetTip()
  self.tip_idx, self.tip_dir, self.tip_true, self.tip_junk = 0, 0, false, false
  self.tip_strong, self.tip_span, self.tip_seen, self.tip_base = false, 0, 0, 0
  self.tip_text = nil
end

function Game:tipText() return self.tip_text end
function Game:tipLeft() return self.over and 0 or math.floor(self.tip_left or 0) end
-- 手上这条还有几个回合见分晓（0 就是没揣着消息）
function Game:tipSpan() return math.floor(self.tip_span or 0) end

local function pick_one(t) return t[math.random(#t)] end

-- 买一条：当场抽好（哪种货、涨还是跌、管几个回合、来势凶不凶、靠不靠得住），
-- 接下来那几个回合里价格会真的往说的方向走 —— 走完才知道准不准。
function Game:buyTip()
  if self.over then return nil, '这一局已经结束了。' end
  if (self.tip_left or 0) <= 0 then return nil, T('这回合的 %1 条已经买过了，等下一回合。', Data.TIPS.per_round) end
  if self:tipSpan() > 0 then
    return nil, T('上一条说的是%1，还有 %2 个回合才见分晓。',
      Data.GOODS[self.tip_idx] and Data.GOODS[self.tip_idx].name or '行情', self:tipSpan())
  end
  if self.cash < Data.TIPS.price then return nil, T('一条要 %1，钱不够。', self:money(Data.TIPS.price)) end
  self.cash = self.cash - Data.TIPS.price
  self.tip_left = (self.tip_left or 0) - 1
  self:resetTip()
  self:tally()
  self.stat.tips = (self.stat.tips or 0) + 1          -- 成就"广撒网"数这个
  if math.random() < (Data.TIPS.junk_chance or 0) then
    self.tip_junk = true
    self.tip_text = pick_one(Data.TIP_JUNK)
    return self.tip_text
  end
  local Tp = Data.TIPS
  self.tip_idx = math.random(#Data.GOODS)
  self.tip_dir = math.random(2) == 1 and 1 or -1
  self.tip_true = math.random() < (Tp.accuracy or 0.7)
  self.tip_strong = math.random() < (Tp.strong_chance or 0)
  local lo = math.floor(Tp.span_lo or 2)
  local hi = math.floor(Tp.span_hi or 3)
  if hi < lo then hi = lo end
  self.tip_span = lo + math.random(0, hi - lo)
  self.tip_seen = self.tip_span
  self.tip_base = self.prices[self.tip_idx] or Data.GOODS[self.tip_idx].base   -- 买的时候的价，最后拿它比
  local words
  if self.tip_dir > 0 then words = self.tip_strong and Data.TIP_UP_STRONG or Data.TIP_UP
  else words = self.tip_strong and Data.TIP_DOWN_STRONG or Data.TIP_DOWN end
  self.tip_text = T('%1：%2接下来 %3 个回合%4。', pick_one(Data.TIP_SOURCES),
    Data.GOODS[self.tip_idx].name, self.tip_seen, pick_one(words))
  return self.tip_text
end

------------------------------------------------------------------ 价格

-- 走一步价格：先往基准价拉回一点（按倍率拉，跌到底也能爬回来），再叠一个随机涨跌，
-- 最后夹在上下限之间
local function step_price(good, p)
  local drift = (math.random() * 2 - 1) * good.vol
  local pull = (good.base / p) ^ Data.PULL - 1
  local np = p * (1 + pull + drift)
  np = math.max(good.base * Data.FLOOR, math.min(good.base * Data.CEIL, np))
  return math.max(1, math.floor(np))
end

-- 一条新闻之后价格也别飞出天际
local function clamp_price(good, p)
  return math.max(1, math.floor(math.max(good.base * 0.25, math.min(good.base * 4, p))))
end

local function pct(a, b) return math.floor((a - b) / b * 100 + 0.5) end

-- 小道消息在这儿兑现：它管的那几个回合里，每回合都把价格往说的方向推一把。
-- 靠得住的消息推的方向跟说的一致，坑人的消息推的方向正好相反 —— 所以跟着做有赚有赔。
-- 走完最后一个回合才结算一句"应验了 / 是假的"，中间不打扰。
-- 放在 clamp_price 后面：它得用得上 clamp_price（前面的都看不见后面声明的 local）
function Game:resolveTip()
  if self.tip_junk then
    self.tip_junk = false
    return T('上回买的那条消息，%1', self.tip_text or '什么也没听着。')
  end
  local i = self.tip_idx or 0
  local span = self:tipSpan()
  if i <= 0 or span <= 0 then return nil end
  local good = Data.GOODS[i]
  if not good then self:resetTip(); return nil end
  local Tp = Data.TIPS
  local dir = self.tip_dir or 1
  local f = self.tip_true and dir or -dir            -- 坑人的消息：反着推
  local push = self.tip_strong and (Tp.push_strong or 0.18) or (Tp.push or 0.10)
  self.prices[i] = clamp_price(good, self.prices[i] * (1 + f * push))
  self.tip_span = span - 1
  if self.tip_span > 0 then return nil end            -- 还在路上，等下一回合
  local from = (self.tip_base or 0) > 0 and self.tip_base or good.base
  local to = self.prices[i]
  local hit = (to - from) * dir > 0
  local d = pct(to, from)
  local move = (d >= 0 and '+' or '') .. d .. '%'
  local msg
  if hit then
    self.stat.tip_true = (self.stat.tip_true or 0) + 1
    msg = T('消息应验了：%1从 %2 走到 %3（%4）。', good.name, self:money(from), self:money(to), move)
  else
    msg = T('消息是假的：%1从 %2 走到 %3（%4），反着来了。', good.name, self:money(from),
      self:money(to), move)
  end
  self:resetTip()
  return msg
end

------------------------------------------------------------------ 仓库

-- 仓库不限制数量：这里只统计手上共有多少件，给玩家看
function Game:held()
  local n = 0
  for i = 1, #Data.GOODS do n = n + (self.inventory[i] or 0) end
  return n
end

function Game:stockValue()
  local v = 0
  for i = 1, #Data.GOODS do v = v + (self.inventory[i] or 0) * (self.prices[i] or 0) end
  return v
end

-- 手上这种货的平均买入价（0 = 没货）。卖出的时候拿它跟现价比一比
function Game:costBasis(i) return math.floor(self.basis[i] or 0) end
-- 这批货现在赚了多少（负数就是亏）
function Game:profit(i)
  local held = self.inventory[i] or 0
  return math.floor(held * ((self.prices[i] or 0) - (self.basis[i] or 0)))
end

-- 进 qty 件货，均价跟着摊：新均价 =（旧货的成本 + 这次花的钱）/ 总件数
local function add_cost(self, i, qty, price)
  local old = self.inventory[i] or 0
  local n = old + qty
  self.inventory[i] = n
  self.basis[i] = n > 0 and math.floor(((self.basis[i] or 0) * old + price * qty) / n + 0.5) or 0
end
function Game:houseValue() return self.owned > 0 and Data.HOUSES[self.owned].price or 0 end
function Game:netWorth() return self.cash + self:stockValue() + self:houseValue() end

-- 相对基准价是便宜还是贵，给玩家一个参考
function Game:tip(i)
  local good = Data.GOODS[i]
  local r = (self.prices[i] or good.base) / good.base
  if r < 0.75 then return '便宜'
  elseif r < 1.10 then return '正常'
  elseif r < 1.60 then return '偏贵'
  else return '很贵' end
end

------------------------------------------------------------------ 一个回合

local function pick_event()
  local total = 0
  for k, e in ipairs(Data.EVENTS) do total = total + e.w end
  local r = math.random() * total
  for k, e in ipairs(Data.EVENTS) do
    r = r - e.w
    if r <= 0 then return e end
  end
  return Data.EVENTS[1]
end

-- 商品名 → 下标（新闻里写的是名字，改商品顺序也不会搞错）
local function good_index(name)
  for i, good in ipairs(Data.GOODS) do if good.name == name then return i end end
  return nil
end

-- 执行一条新闻：改价格、给钱、扣钱、损失货物。返回一句给玩家看的话。
function Game:fireEvent(messages)
  local e = pick_event()
  -- 有些事件（白得一张刮刮乐、只是说句话）没有倍率，用到的时候才算
  local f = (e.lo ~= nil and e.hi ~= nil) and (e.lo + math.random() * (e.hi - e.lo)) or nil
  if e.kind == 'good' then
    local i = good_index(e.target)
    if not i then messages[#messages + 1] = e.text; return e end
    self.prices[i] = clamp_price(Data.GOODS[i], self.prices[i] * f)
    messages[#messages + 1] = e.text
  elseif e.kind == 'all' then
    for i, good in ipairs(Data.GOODS) do self.prices[i] = clamp_price(good, self.prices[i] * f) end
    messages[#messages + 1] = e.text
  elseif e.kind == 'cash' then
    local amt = math.floor(f)
    if amt >= 0 then
      self.cash = self.cash + amt
      messages[#messages + 1] = T('%1 你多了 %2。', e.text, self:money(amt))
    else
      local d = math.min(self.cash, -amt)
      self.cash = self.cash - d
      messages[#messages + 1] = T('%1 你少了 %2。', e.text, self:money(d))
    end
  elseif e.kind == 'cash_rate' then
    local amt = math.floor(self.cash * f)
    if amt > 0 then
      self.cash = self.cash + amt
      messages[#messages + 1] = T('%1 你多了 %2。', e.text, self:money(amt))
    else
      messages[#messages + 1] = e.text
    end
  elseif e.kind == 'cash_rate_sub' then
    local amt = math.min(self.cash, math.floor(self.cash * f))
    if amt > 0 then
      self.cash = self.cash - amt
      messages[#messages + 1] = T('%1 你少了 %2。', e.text, self:money(amt))
    else
      messages[#messages + 1] = e.text
    end
  elseif e.kind == 'lose_goods' then
    local held = {}
    for i = 1, #Data.GOODS do if (self.inventory[i] or 0) > 0 then held[#held + 1] = i end end
    if #held == 0 then
      messages[#messages + 1] = e.text .. '还好仓库是空的。'
    else
      local i = held[math.random(#held)]
      local lost = math.floor(self.inventory[i] * f)
      self.inventory[i] = self.inventory[i] - lost
      if self.inventory[i] <= 0 then self.inventory[i] = 0; self.basis[i] = 0 end
      messages[#messages + 1] = T('%1 你损失了 %2 件%3。', e.text, lost, Data.GOODS[i].name)
    end
  elseif e.kind == 'free_goods' then
    local i = e.target and good_index(e.target) or math.random(#Data.GOODS)
    if not i then i = math.random(#Data.GOODS) end
    local n = math.max(1, math.floor(f))
    add_cost(self, i, n, 0)                     -- 白得的：成本算 0，卖多少赚多少
    messages[#messages + 1] = T('%1 你多了 %2 件%3。', e.text, n, Data.GOODS[i].name)
  elseif e.kind == 'free_lotto' then
    self.lotto_free = (self.lotto_free or 0) + 1
    messages[#messages + 1] = e.text .. '随时可以去刮。'
  else
    messages[#messages + 1] = e.text
  end
  return e
end

-- 进入下一回合：价格先走一步，再抽新闻。
-- 返回两摞话：events 是这一回合的特殊事件（新闻说的话），moves 是涨跌榜。分开给界面摆。
function Game:nextRound()
  local events, moves = {}, {}
  if self.over then return { events = events, moves = moves, over = true } end
  for i = 1, #Data.GOODS do self.prev[i] = self.prices[i] end
  for i, good in ipairs(Data.GOODS) do self.prices[i] = step_price(good, self.prices[i]) end
  -- 手上那条小道消息在这儿推价格：随机涨跌走完之后，再往消息说的方向推一把
  local tip_msg = self:resolveTip()
  if math.random() < Data.EVENT_CHANCE then
    local e = self:fireEvent(events)
    self:note(e.text)
  end
  -- 涨跌榜：只报动过 8% 以上的，最多两样
  local best_up, best_down = nil, nil
  for i, good in ipairs(Data.GOODS) do
    local d = pct(self.prices[i], self.prev[i])
    if not best_up or d > best_up.d then best_up = { idx = i, d = d } end
    if not best_down or d < best_down.d then best_down = { idx = i, d = d } end
  end
  if best_up and best_up.d >= 8 then
    moves[#moves + 1] = T('▲ %1 涨到 %2（+%3%）', Data.GOODS[best_up.idx].name, self:money(self.prices[best_up.idx]), best_up.d)
  end
  if best_down and best_down.d <= -8 then
    moves[#moves + 1] = T('▼ %1 跌到 %2（%3%）', Data.GOODS[best_down.idx].name, self:money(self.prices[best_down.idx]), best_down.d)
  end
  self.round = self.round + 1
  self.lotto_left = Data.LOTTERY.per_round       -- 新的一回合，又有三张名额
  self.tip_left = Data.TIPS.per_round            -- 消息也又能买了
  self:tally()
  local done = false
  if self.round > Data.MAX_ROUNDS then
    self.round = Data.MAX_ROUNDS
    self.over = true
    done = true
  end
  if done then events[#events + 1] = T('第 %1 回合结束，60 个回合用完了。', Data.MAX_ROUNDS) end
  return { events = events, moves = moves, tip = tip_msg, over = self.over }
end

-- 收摊：最后一回合自己结束（或者六十回合走完）。结算画面由界面弹
function Game:finish()
  self.over = true
  return true
end

------------------------------------------------------------------ 彩票站：六格刮刮乐

-- 一个格子刮出什么：按权重抽一个奖品下标
local function pick_cell()
  local total = 0
  for _k, p in ipairs(Data.LOTTERY.CELL_PRIZES) do total = total + p.w end
  local r = math.random() * total
  for k, p in ipairs(Data.LOTTERY.CELL_PRIZES) do
    r = r - p.w
    if r <= 0 then return k end
  end
  return 1
end
local function cell_amount(k)
  local p = Data.LOTTERY.CELL_PRIZES[math.floor(k or 0)]
  return p and p.amount or 0
end
local function n_cells() return Data.LOTTERY.cells end

-- 存档：六个格子的奖品下标压成一个六位数（每格一位），刮开情况压成一个位掩码
local function pack_card(cells)
  local v = 0
  if not cells then return 0 end
  for k = 1, n_cells() do v = v * 10 + math.floor(cells[k] or 0) end
  return v
end
local function pack_mask(open)
  local v = 0
  if not open then return 0 end
  for k = n_cells(), 1, -1 do v = v * 2 + (open[k] and 1 or 0) end
  return v
end

-- 这一回合还能买几张（白得的券不算名额，随时能用）
function Game:lotteryLeft() return self.over and 0 or math.floor(self.lotto_left or 0) end
function Game:lotteryFree() return math.floor(self.lotto_free or 0) end
function Game:lotteryPool() return math.floor(self.lotto_pool or 0) end

-- 手上那张卡：返回（六格的金额，六格刮开了没有），没有卡就是 nil
function Game:lotteryCard()
  local c, o = self.lotto_cells, self.lotto_open
  if not c or #c ~= n_cells() then return nil end
  local amounts = {}
  for k = 1, n_cells() do amounts[k] = cell_amount(c[k]) end
  return amounts, o
end

-- 能不能再买一张：要么这回合还有名额且掏得出钱，要么手上有一张白得的券。
-- 手上还捏着一张没刮完的不算：先刮完那张再说。
function Game:canLottery()
  if self.over then return false, '这一局已经结束了。' end
  if self.lotto_cells then return false, '手上那张还没刮完呢，先刮完再说。' end
  if (self.lotto_free or 0) > 0 then return true end
  if (self.lotto_left or 0) <= 0 then return false, T('这回合的 %1 张已经买完了，等下一回合。', Data.LOTTERY.per_round) end
  if self.cash < Data.LOTTERY.price then return false, T('一张要 %1，钱不够。', self:money(Data.LOTTERY.price)) end
  return true
end

-- 开一张新卡之前走这一步：要么兑掉一张白得的券，要么掏钱占一个名额，
-- 同时把 ¥10 注进本期奖池
local function take_ticket(self)
  if (self.lotto_free or 0) > 0 then
    self.lotto_free = self.lotto_free - 1
  else
    self.cash = self.cash - Data.LOTTERY.price
    self.lotto_left = (self.lotto_left or 0) - 1
    self.lotto_spent = (self.lotto_spent or 0) + Data.LOTTERY.price
  end
  self.lotto_n = (self.lotto_n or 0) + 1
  self.lotto_pool = (self.lotto_pool or 0) + Data.LOTTERY.pool_in
  return true
end

-- 买一张：六个格子的奖当场抽好存着，玩家一格一格点开（退出重进也不会丢）
function Game:buyLottery()
  local ok, err = self:canLottery()
  if not ok then return nil, err end
  take_ticket(self)
  local c, o = {}, {}
  for k = 1, n_cells() do c[k] = pick_cell(); o[k] = false end
  self.lotto_cells, self.lotto_open = c, o
  return true
end

-- 刮开第 k 格。返回这一格的金额，已经刮过或没这张卡就返回 nil
function Game:scratchCell(k)
  local c, o = self.lotto_cells, self.lotto_open
  k = math.floor(tonumber(k) or 0)
  if not c or k < 1 or k > n_cells() then return nil end
  if o[k] then return nil end
  o[k] = true
  local a = cell_amount(c[k])
  self:tally()
  if a > (self.stat.max_cell or 0) then self.stat.max_cell = a end   -- 成就"锦鲤附体"看这个
  return a
end

-- 六个格子里刮开了几格
function Game:cardOpenCount()
  local o = self.lotto_open
  if not o then return 0 end
  local n = 0
  for k = 1, n_cells() do if o[k] then n = n + 1 end end
  return n
end
-- 已经刮开的那几格一共多少钱（给玩家看着攒）
function Game:cardRevealedTotal()
  local c, o = self.lotto_cells, self.lotto_open
  if not c then return 0 end
  local v = 0
  for k = 1, n_cells() do if o[k] then v = v + cell_amount(c[k]) end end
  return v
end
-- 六个都刮开了没有
function Game:cardDone() return self.lotto_cells ~= nil and self:cardOpenCount() >= n_cells() end

-- 交回这张卡：把已经刮开的那几格的金额加起来入账，再抽一次奖池机会。
-- 没刮开的格子不算 —— 不刮就没有钱。返回（总金额，六个格子各自的金额，额外发生的事）
function Game:cashCard()
  local c, o = self.lotto_cells, self.lotto_open
  if not c or not o then return nil end
  local amounts, total = {}, 0
  for k = 1, n_cells() do
    amounts[k] = cell_amount(c[k])
    if o[k] then total = total + amounts[k] end
  end
  local opened = self:cardOpenCount()
  self.lotto_cells, self.lotto_open = nil, nil
  self:tally()
  if total > 0 then
    self.cash = self.cash + total
    self.lotto_win = (self.lotto_win or 0) + total
  elseif opened >= n_cells() then
    self.stat.blank_cards = (self.stat.blank_cards or 0) + 1        -- 成就"空手而归"
  end
  local msgs = {}
  -- 每张票都有一次机会独得奖池，中不中奖跟卡上刮出来的钱各算各的
  if math.random(Data.LOTTERY.pool_chance) == 1 then
    local pool = self:lotteryPool()
    if pool > 0 then
      self.cash = self.cash + pool
      self.lotto_win = (self.lotto_win or 0) + pool
      self.lotto_pool = 0
      self.stat.pool_wins = (self.stat.pool_wins or 0) + 1          -- 成就"奖池猎手"
      msgs[#msgs + 1] = T('独得本期奖池 %1！奖池清空，从头再攒。', self:money(pool))
    end
  end
  return total, amounts, msgs
end


-- 记一条行情，最多留 4 条，给"行情"那一屏翻
function Game:note(s)
  if not s or s == '' then return end
  table.insert(self.log, 1, s)
  while #self.log > 4 do table.remove(self.log) end
end

------------------------------------------------------------------ 买卖

function Game:maxBuy(i)
  local price = self.prices[i]
  if not price or price <= 0 then return 0 end
  return math.max(0, math.floor(self.cash / price))
end

function Game:buy(i, qty)
  local price = self.prices[i]
  qty = math.floor(tonumber(qty) or 0)
  if qty <= 0 then return false end
  if not price then return false, '这里不做这种货。' end
  local cost = price * qty
  if cost > self.cash then return false, '钱不够。' end
  self.cash = self.cash - cost
  add_cost(self, i, qty, price)
  mark_traded(self, i)
  self:tally()
  return true
end

function Game:sell(i, qty)
  local price = self.prices[i]
  qty = math.floor(tonumber(qty) or 0)
  if qty <= 0 then return false end
  if not price then return false, '这里没人收这种货。' end
  if qty > (self.inventory[i] or 0) then return false, '手上没有这么多。' end
  local gain = math.floor(qty * (price - (self.basis[i] or 0)))   -- 这一笔赚了多少
  self.cash = self.cash + price * qty
  self.inventory[i] = self.inventory[i] - qty
  if self.inventory[i] <= 0 then self.inventory[i] = 0; self.basis[i] = 0 end
  mark_traded(self, i)
  self:tally()                                                    -- 先把 stat 摆好再往里记
  if gain > (self.stat.best_trade or 0) then self.stat.best_trade = gain end
  return true
end

-- 一键清仓：把手上的货全卖了，返回（件数，收入）
function Game:sellAll()
  local n, got = 0, 0
  for i = 1, #Data.GOODS do
    local held = self.inventory[i] or 0
    if held > 0 and self.prices[i] then
      self.cash = self.cash + self.prices[i] * held
      got = got + self.prices[i] * held
      n = n + held
      self.inventory[i] = 0
      self.basis[i] = 0
    end
  end
  return n, got
end

------------------------------------------------------------------ 买房

-- 买第 i 档要掏多少钱：已经有一套的话，旧房按原价抵扣，只补差价
function Game:houseCost(i)
  local h = Data.HOUSES[i]
  if not h then return nil end
  if self.owned <= 0 then return h.price end
  return h.price - Data.HOUSES[self.owned].price
end

function Game:canBuyHouse(i)
  local cost = self:houseCost(i)
  return cost ~= nil and i > self.owned and self.cash >= cost
end

function Game:buyHouse(i)
  if not Data.HOUSES[i] then return false, '没有这一档。' end
  if i <= self.owned then return false, '你已经住得更好了。' end
  local cost = self:houseCost(i)
  if self.cash < cost then return false, T('钱不够，还差 %1。', self:money(cost - self.cash)) end
  self.cash = self.cash - cost
  self.owned = i
  self:tally()
  self.stat.house_buys = (self.stat.house_buys or 0) + 1
  if (self.stat.first_round or 0) <= 0 then self.stat.first_round = self.round end
  return true, T('你买下了%1，成了有房的人。', Data.HOUSES[i].name)
end

function Game:rank()
  if self.owned > 0 then return Data.HOUSES[self.owned].rank end
  return Data.NO_HOUSE_RANK
end

------------------------------------------------------------------ 存档

function Game:serialize()
  local inv, pr, pv, ba = {}, {}, {}, {}
  for i = 1, #Data.GOODS do
    inv[i] = tostring(math.floor(self.inventory[i] or 0))
    pr[i] = tostring(math.floor(self.prices[i] or 0))
    pv[i] = tostring(math.floor(self.prev[i] or 0))
    ba[i] = tostring(math.floor(self.basis[i] or 0))
  end
  local s = self.stat or self:newStat()
  return {
    round = self.round, cash = self.cash, owned = self.owned,
    inventory = inv, prices = pr, prev = pv, basis = ba,
    over = self.over, log = self.log,
    -- 小道消息：还能买几条 / 哪种货 / 涨还是跌 / 靠不靠得住 / 来势凶不凶 /
    -- 还剩几个回合 / 一共几个回合 / 买的时候的价 / 是不是废话；原文另存一行
    tip = { self.tip_left or 0, self.tip_idx or 0, self.tip_dir or 0,
      (self.tip_true and 1 or 0), (self.tip_strong and 1 or 0),
      self.tip_span or 0, self.tip_seen or 0, math.floor(self.tip_base or 0),
      (self.tip_junk and 1 or 0) },
    tiptxt = self.tip_text or '',
    -- 这一局的账：成就看它。跨局累加的那些（刮了几张、买过几条消息）在界面那边
    stat = { s.best_trade or 0, s.max_hold or 0, s.house_buys or 0, s.first_round or 0,
      s.max_net or 0, s.traded or 0, s.tips or 0, s.max_cell or 0,
      s.blank_cards or 0, s.pool_wins or 0 },
    lotto_left = self.lotto_left, lotto_free = self.lotto_free,
    lotto_n = self.lotto_n, lotto_spent = self.lotto_spent,
    lotto_win = self.lotto_win, lotto_pool = self.lotto_pool,
    -- 手上那张卡：六个格子的奖品下标压成一个六位数，刮开了哪几格压成一个位掩码
    lotto_card = pack_card(self.lotto_cells),
    lotto_mask = pack_mask(self.lotto_open),
  }
end

function Game:load(state)
  if type(state) ~= 'table' or not state.round or not state.inventory then return false end
  self:newGame()                       -- 先把所有字段摆好，再用存档盖上去
  self.round = math.floor(tonumber(state.round) or 1)
  self.cash = math.floor(tonumber(state.cash) or Data.START_CASH)
  self.owned = math.floor(tonumber(state.owned) or 0)
  self.inventory, self.prices, self.prev, self.log, self.basis = {}, {}, {}, {}, {}
  for i, good in ipairs(Data.GOODS) do
    self.inventory[i] = math.floor(tonumber(state.inventory[i]) or 0)
    local p = math.floor(tonumber(state.prices[i]) or 0)
    self.prices[i] = p > 0 and p or math.max(1, math.floor(good.base))
    self.prev[i] = math.floor(tonumber(state.prev[i]) or 0)
    if self.prev[i] <= 0 then self.prev[i] = self.prices[i] end
    -- 老存档没有 basis：拿现价当买入价，总比没有强
    self.basis[i] = math.floor(tonumber(state.basis and state.basis[i]) or (self.inventory[i] > 0 and self.prices[i] or 0))
    if self.inventory[i] <= 0 then self.basis[i] = 0 end
  end
  self.over = state.over == true or state.over == '1'
  -- 小道消息：老存档没有这一行，读不到就是没买过
  self:resetTip()
  self.tip_left = Data.TIPS.per_round
  if type(state.tip) == 'table' then
    local tp = state.tip
    local yn = function(v) return v == 1 or v == '1' or v == true end
    self.tip_left = math.floor(tonumber(tp[1]) or Data.TIPS.per_round)
    local idx = math.floor(tonumber(tp[2]) or 0)
    self.tip_idx = (idx >= 1 and idx <= #Data.GOODS) and idx or 0
    self.tip_dir = (tonumber(tp[3]) or 0) < 0 and -1 or 1
    self.tip_true = yn(tp[4])
    self.tip_strong = yn(tp[5])
    self.tip_span = math.max(0, math.floor(tonumber(tp[6]) or 0))
    self.tip_seen = math.max(0, math.floor(tonumber(tp[7]) or 0))
    self.tip_base = math.floor(tonumber(tp[8]) or 0)
    self.tip_junk = yn(tp[9])
    if self.tip_idx <= 0 and not self.tip_junk then self.tip_span = 0 end
    if self.tip_span <= 0 then self.tip_idx = 0 end
    if self.tip_base <= 0 then self.tip_base = self.prices[self.tip_idx] or 0 end
    -- 消息原文存下来：退出重进还能看见那条消息说了什么（老存档没有这一行，就当没买过）
    self.tip_text = (type(state.tiptxt) == 'string' and state.tiptxt ~= '') and state.tiptxt or nil
    if not self.tip_text then self:resetTip() end
  end
  -- 这一局的账：没有就从头记
  self.stat = self:newStat()
  if type(state.stat) == 'table' then
    local f = function(n) return math.floor(tonumber(n) or 0) end
    self.stat.best_trade = f(state.stat[1])
    self.stat.max_hold = f(state.stat[2])
    self.stat.house_buys = f(state.stat[3])
    self.stat.first_round = f(state.stat[4])
    self.stat.max_net = f(state.stat[5])
    self.stat.traded = f(state.stat[6])
    self.stat.tips = f(state.stat[7])
    self.stat.max_cell = f(state.stat[8])
    self.stat.blank_cards = f(state.stat[9])
    self.stat.pool_wins = f(state.stat[10])
  end
  self.lotto_left = math.floor(tonumber(state.lotto_left) or Data.LOTTERY.per_round)
  self.lotto_free = math.floor(tonumber(state.lotto_free) or 0)
  self.lotto_n = math.floor(tonumber(state.lotto_n) or 0)
  self.lotto_spent = math.floor(tonumber(state.lotto_spent) or 0)
  self.lotto_win = math.floor(tonumber(state.lotto_win) or 0)
  -- 老存档没有奖池：那就从开局的底子开始攒
  self.lotto_pool = math.floor(tonumber(state.lotto_pool) or Data.LOTTERY.pool_start)
  -- 手上那张没刮完的卡要原样读回来。老存档那一位放的是别的东西，读出来不成样子就当没卡
  self.lotto_cells, self.lotto_open = nil, nil
  local card = math.floor(tonumber(state.lotto_card) or 0)
  local mask = math.floor(tonumber(state.lotto_mask) or 0)
  if card > 0 then
    local s = string.format('%0' .. n_cells() .. 'd', card % (10 ^ n_cells()))
    local c, o, bad = {}, {}, false
    for k = 1, n_cells() do
      local idx = math.floor(tonumber(s:sub(k, k)) or 0)
      if not Data.LOTTERY.CELL_PRIZES[idx] then bad = true; break end
      c[k] = idx
      o[k] = mask % 2 == 1
      mask = math.floor(mask / 2)
    end
    if not bad then self.lotto_cells, self.lotto_open = c, o end
  end
  if type(state.log) == 'table' then
    for k, s in ipairs(state.log) do if type(s) == 'string' then self.log[#self.log + 1] = s end end
  end
  if #self.log == 0 then self.log[1] = T('开局：%1 的启动资金，%2 个回合，赚够钱买一套房。', self:money(Data.START_CASH), Data.MAX_ROUNDS) end
  if self.round > Data.MAX_ROUNDS then self.round = Data.MAX_ROUNDS; self.over = true end
  return true
end

return Game
end

-- 买房记 for XTOS Licorice (API 2.9)：设备上的那一屏。
--
-- 一屏看完：回合、现金、净资产、库存、房产，下面八行行情，再下面六个按钮。点商品买卖，
-- 点"下一回合"推进；买房、清仓、行情、成绩都在按钮里。每一步都自动存档，退出也存。
--
-- 所有 ctx.* 都是这个 API 上的方法：一律用冒号调用。

local W, H = 480, 800
local Data = require('fangchan_data')
local Game = require('fangchan_game')
local T = require('ffi/util').template

local game
local difficulty = 1                     -- Data.DIFFICULTY 的下标：1 = 简单
-- best_net / best_house 是历史最好成绩；house_wins[i] 是第 i 档房子历年一共买到过几次
local best_net, best_house = 0, 0
local house_wins = {}
for _k = 1, #Data.HOUSES do house_wins[_k] = 0 end
local modal = nil                        -- 弹窗：{ title, lines, rows = { { {标签, 函数, 可用}, .. }, .. }, cancel }
local status = ''
local ERR = nil
local lottery_box, difficulty_box, end_game   -- 下面才定义，按钮表先挂个名字
-- 成就：unlocked[id] = true 是历年来点亮过的；tot 是跨局累加的几个计数器
local unlocked = {}
local tot = { tips = 0, cards = 0 }
local pending_ach = {}                   -- 攒着的成就，等手头这件事办完再报

------------------------------------------------------------------ 小工具

local function refresh() pcall(function() ctx.invalidate() end) end
local function fmt(n) return Game.format(n) end

-- 一个 UTF-8 字符数组（中文没有空格，只能一个字一个字地量着折行）
local function chars(s)
  local out = {}
  for _p, c in utf8.codes(s) do out[#out + 1] = utf8.char(c) end
  return out
end
-- 掉最后一个字符，整个 UTF-8 序列一起掉
local function drop_last(s) return (s:gsub('[%z\1-\127\192-\255][\128-\191]*$', '')) end
-- 最多 n 个字节，且不把一个字切成两半
local function short(s, n)
  s = tostring(s)
  if #s <= n then return s end
  local t = s:sub(1, n)
  while #t > n - 1 or (#t > 0 and t:sub(-1):byte() >= 128 and not utf8.len(t)) do t = drop_last(t) end
  return t .. '~'
end

local function font(name) return ctx.fonts and ctx.fonts[name] end
local function width(f, s)
  local ok, w = pcall(function() return f:measure(s) end)
  return (ok and type(w) == 'number') and w or #s * 11
end
local function line_h(name)
  local ok, h = pcall(function() return font(name).line_height end)
  return (ok and tonumber(h)) or (name == 'large' and 30 or name == 'small' and 20 or 24)
end

-- 折行：中文一个字一个 token，西文按空格分词，行宽超了就换行
local function tokenize(s)
  local out, word = {}, ''
  local function flush() if word ~= '' then out[#out + 1] = word; word = '' end end
  for _p, c in utf8.codes(s) do
    local ch = utf8.char(c)
    if ch == ' ' or ch == '\t' then flush(); out[#out + 1] = ' '
    elseif c >= 0x2E80 then flush(); out[#out + 1] = ch      -- 汉字和全角标点：一个字一段
    else word = word .. ch end
  end
  flush()
  return out
end

local function wrap(s, fname, maxw)
  local f, out = font(fname), {}
  for para in (tostring(s) .. '\n'):gmatch('([^\n]*)\n') do
    local line = ''
    for _k, tk in ipairs(tokenize(para)) do
      if tk == ' ' then
        if line ~= '' and line:sub(-1) ~= ' ' then line = line .. ' ' end
      else
        local join = ''
        local last = line:byte(-1)
        -- 两边只要有一边不是 ASCII（汉字、¥、·）就紧挨着排，中文不用空格分词
        local cjk = tk:byte() >= 0x80 or (last ~= nil and last >= 0x80)
        if line ~= '' and not cjk and line:sub(-1) ~= ' ' then join = ' ' end
        local cand = line .. join .. tk
        if line ~= '' and width(f, cand) > maxw then
          out[#out + 1] = (line:gsub(' +$', ''))
          line = tk
        else
          line = cand
        end
      end
    end
    out[#out + 1] = (line:gsub(' +$', ''))
  end
  return out
end

------------------------------------------------------------------ 存档

local function read(name)
  local ok, s = pcall(function() return ctx.storage:read(name) end)
  return (ok and type(s) == 'string') and s or nil
end
local function write(name, s) pcall(function() ctx.storage:write(name, s) end) end

local function kv(s)
  local t = {}
  for k, v in (s or ''):gmatch('([%w_]+)=([^\n]*)') do t[k] = (v:gsub('%s+$', '')) end
  return t
end

-- 存档写成 key=value 的行：设备没有 JSON 编码器，这样也够读回来
local function save()
  if not game then return end
  local st = game:serialize()
  write('game.txt', table.concat({
    'round=' .. st.round, 'cash=' .. math.floor(st.cash), 'owned=' .. st.owned,
    'inv=' .. table.concat(st.inventory, ','), 'prices=' .. table.concat(st.prices, ','),
    'prev=' .. table.concat(st.prev, ','), 'basis=' .. table.concat(st.basis, ','),
    'over=' .. (st.over and '1' or '0'),
    -- lotto= 这一串往前加过字段：老存档位数对不上，读不到的按开局处理
    'lotto=' .. table.concat({ st.lotto_left, st.lotto_free, st.lotto_n, st.lotto_spent,
      st.lotto_win, st.lotto_card, st.lotto_pool, st.lotto_mask }, ','),
    'log=' .. table.concat(st.log, '|'),
    'tip=' .. table.concat(st.tip, ','),
    'tiptxt=' .. (st.tiptxt or ''),
    'stat=' .. table.concat(st.stat, ','),
  }, '\n'))
end

local function load_saved()
  local t = kv(read('game.txt'))
  if not t.round then return false end
  local function list(s)
    local out, i = {}, 0
    for v in ((s or '') .. ','):gmatch('([^,]*),') do i = i + 1; out[i] = tonumber(v) end
    return out
  end
  local log = {}
  for s in (t.log or ''):gmatch('[^|]+') do log[#log + 1] = s end
  local lt = list(t.lotto)
  return game:load({
    round = tonumber(t.round), cash = tonumber(t.cash), owned = tonumber(t.owned),
    inventory = list(t.inv), prices = list(t.prices), prev = list(t.prev), basis = list(t.basis),
    over = t.over == '1', log = log,
    lotto_left = lt[1], lotto_free = lt[2], lotto_n = lt[3],
    lotto_spent = lt[4], lotto_win = lt[5], lotto_card = lt[6],
    lotto_pool = lt[7], lotto_mask = lt[8],
    tip = list(t.tip), tiptxt = t.tiptxt, stat = list(t.stat),
  })
end

-- 难度单独存一份：换难度不动这一局，新开一局也还是这个难度
local function save_settings() write('settings.txt', 'difficulty=' .. difficulty) end
local function load_settings()
  local t = kv(read('settings.txt'))
  local d = math.floor(tonumber(t.difficulty) or 1)
  difficulty = Data.DIFFICULTY[d] and d or 1
end
local function diff() return Data.DIFFICULTY[difficulty] end
local function show_base() return diff().show_base end      -- 显不显示基准价
local function show_tip() return diff().show_tip end        -- 提不提示便宜还是贵

-- best.txt 记四样：最高净资产、买过最好的房子、每一档房子一共买到过几次（逗号分隔）、
-- 点亮的成就（逗号分隔的 id）、以及几个跨局累加的计数器
local function save_best()
  local w = {}
  for i = 1, #Data.HOUSES do w[i] = tostring(math.floor(house_wins[i] or 0)) end
  local a = {}
  for _k, ac in ipairs(Data.ACHIEVEMENTS) do if unlocked[ac.id] then a[#a + 1] = ac.id end end
  write('best.txt', 'net=' .. math.floor(best_net) .. '\nhouse=' .. best_house
    .. '\nwins=' .. table.concat(w, ',')
    .. '\nach=' .. table.concat(a, ',')
    .. '\ntot=' .. math.floor(tot.tips or 0) .. ',' .. math.floor(tot.cards or 0))
end
local function load_best()
  local t = kv(read('best.txt'))
  best_net = tonumber(t.net) or 0
  best_house = tonumber(t.house) or 0
  local i = 0
  for v in ((t.wins or '') .. ','):gmatch('([^,]*),') do
    i = i + 1
    if i <= #Data.HOUSES then house_wins[i] = math.floor(tonumber(v) or 0) end
  end
  unlocked = {}
  for id in (t.ach or ''):gmatch('[^,]+') do unlocked[id] = true end
  local n = 0
  for v in ((t.tot or '') .. ','):gmatch('([^,]*),') do
    n = n + 1
    if n == 1 then tot.tips = math.floor(tonumber(v) or 0)
    elseif n == 2 then tot.cards = math.floor(tonumber(v) or 0) end
  end
end
local function record(net, house)
  if net > best_net then best_net = net end
  if house > best_house then best_house = house end
  save_best()
end

------------------------------------------------------------------ 成就

-- 点亮一个成就（第一次点亮才算，重复的不再报）
local function unlock(id)
  if unlocked[id] then return false end
  local found = nil
  for _k, ac in ipairs(Data.ACHIEVEMENTS) do if ac.id == id then found = ac; break end end
  if not found then return false end
  unlocked[id] = true
  save_best()
  pending_ach[#pending_ach + 1] = found
  return true
end

local function unlocked_count()
  local n = 0
  for _k, ac in ipairs(Data.ACHIEVEMENTS) do if unlocked[ac.id] then n = n + 1 end end
  return n
end

-- 看看这一刻够得上哪几个成就。随时可以调，不会重复报
local function check_ach()
  local s = game.stat or {}
  if (s.best_trade or 0) >= 1000 then unlock('first_gold') end
  if game.round <= 5 and game:netWorth() >= Data.START_CASH * 2 then unlock('double') end
  if game.owned > 0 then
    unlock('house_first')
    if (s.house_buys or 0) >= 2 then unlock('house_up') end
    if game.owned >= #Data.HOUSES then unlock('villa') end
  end
  if (tot.cards or 0) >= 10 then unlock('scratch10') end
  if (s.max_cell or 0) >= 5000 then unlock('big_cell') end
  if (s.pool_wins or 0) >= 1 then unlock('pool') end
  if (s.blank_cards or 0) >= 1 then unlock('blank_card') end
  if (s.max_hold or 0) >= 100 then unlock('hoarder') end
  if (tot.tips or 0) >= 10 then unlock('tipster') end
  if (s.tip_true or 0) >= 3 then unlock('tip3') end
  if (s.tips or 0) >= 5 then unlock('tip5') end
  if (s.max_net or 0) >= 100000 then unlock('rich') end
  if game:tradedCount() >= #Data.GOODS then unlock('allgoods') end
end

-- 手头这件事办完了，把攒下的成就报一声（一次报一个，不打断连着的操作）。
-- 它要调 show()，可 show 在下面的弹窗段才声明 —— 这儿先挂个名字，等 show 有了再赋值。
local flush_ach
-- 买成了第 i 档：这一档的累计次数 +1
local function record_house(i)
  if Data.HOUSES[i] then
    house_wins[i] = (house_wins[i] or 0) + 1
    save_best()
  end
end
local function total_house_wins()
  local n = 0
  for i = 1, #Data.HOUSES do n = n + (house_wins[i] or 0) end
  return n
end

------------------------------------------------------------------ 弹窗

local BOX_X, BOX_W, ROW_H, GAP = 20, W - 40, 56, 10
-- 刮刮卡的格子：一行三个，两行六个
local CELL_W, CELL_H, CELL_GAP = 126, 100, 11

local function layout_modal(m)
  local lines = {}
  if m.title then
    for _k, l in ipairs(wrap(m.title, 'medium', BOX_W - 40)) do lines[#lines + 1] = { l, 'medium' } end
  end
  for _k, s in ipairs(m.lines or {}) do
    for _k, l in ipairs(wrap(s, m.big and 'large' or 'small', BOX_W - 40)) do lines[#lines + 1] = { l, m.big and 'large' or 'small' } end
  end
  local th = 0
  for _k, l in ipairs(lines) do th = th + line_h(l[2]) + 4 end
  local nrow = m.cells and math.ceil(#m.cells / 3) or 0
  local ch = nrow > 0 and (nrow * CELL_H + (nrow - 1) * CELL_GAP + 8) or 0
  local h = 20 + th + 14 + ch + #m.rows * (ROW_H + GAP) + 10
  local y = math.max(150, math.floor((H - h) / 2))
  if y + h > H - 30 then y = math.max(10, H - 30 - h) end
  local cy = y + 20 + th + 14
  local cells = {}
  for k = 1, (m.cells and #m.cells or 0) do
    local c, r = (k - 1) % 3, (k - 1) // 3
    cells[k] = { x = BOX_X + 20 + c * (CELL_W + CELL_GAP), y = cy + r * (CELL_H + CELL_GAP),
      w = CELL_W, h = CELL_H, c = m.cells[k] }
  end
  local btns, by = {}, cy + ch
  for _k, row in ipairs(m.rows) do
    local n = #row
    local bw = math.floor((BOX_W - 40 - (n - 1) * GAP) / n)
    for k, btn in ipairs(row) do
      btns[#btns + 1] = { x = BOX_X + 20 + (k - 1) * (bw + GAP), y = by, w = bw, h = ROW_H, b = btn }
    end
    by = by + ROW_H + GAP
  end
  return lines, btns, y, h, cells
end

-- 还没刮开的那一层涂层：45 度的斜线，画在 (x,y,w,h) 这个框里
local function hatch(gg, x, y, w, h)
  local step = 22
  local d = -h + step
  while d < w - step do
    local ax, ay, bx, by
    if d < 0 then ax, ay = x, y + h + d else ax, ay = x + d, y + h end
    if d + h <= w then bx, by = x + d + h, y else bx, by = x + w, y + h - (w - d) end
    pcall(function() gg:line(ax, ay, bx, by) end)
    d = d + step
  end
end

-- 刮出来是笑脸：画一张脸。字体里未必有 ☺ 这个字符，用线条画最保险
local function smiley(gg, cx, cy)
  pcall(function()
    gg:circle(cx, cy - 2, 23)
    gg:circle(cx - 9, cy - 11, 2)
    gg:circle(cx + 9, cy - 11, 2)
    gg:polyline({ cx - 13, cy + 5, cx - 7, cy + 12, cx, cy + 14, cx + 7, cy + 12, cx + 13, cy + 5 })
  end)
end

-- 一格：没刮开是涂着斜线的方块，刮开了就是笑脸或者金额
local function draw_cell(gg, cl)
  local c = cl.c
  gg:rect(cl.x, cl.y, cl.w, cl.h, { line_width = 2 })
  if c.open then
    if (c.amount or 0) > 0 then
      local s = game:money(c.amount)
      local f = font('large')
      while #s > 1 and width(f, s) > cl.w - 12 do s = s:sub(1, -2) end
      local tf = width(f, s) > cl.w - 12 and font('medium') or f
      gg:text(cl.x + math.floor((cl.w - width(tf, s)) / 2), cl.y + math.floor((cl.h - line_h('medium')) / 2), s, { font = tf })
    else
      smiley(gg, cl.x + cl.w // 2, cl.y + cl.h // 2)
    end
  else
    hatch(gg, cl.x + 4, cl.y + 4, cl.w - 8, cl.h - 8)
  end
end

local function draw_modal(gg)
  local lines, btns, y, h, cells = layout_modal(modal)
  gg:rect(BOX_X, y, BOX_W, h)
  gg:rect(BOX_X + 3, y + 3, BOX_W - 6, h - 6)
  local ty = y + 20
  for _k, l in ipairs(lines) do gg:text(BOX_X + 20, ty, l[1], { font = font(l[2]) }); ty = ty + line_h(l[2]) + 4 end
  for _k, cl in ipairs(cells) do draw_cell(gg, cl) end
  for _k, bt in ipairs(btns) do
    local enabled = bt.b[3] ~= false
    gg:rect(bt.x, bt.y, bt.w, bt.h, { line_width = enabled and 2 or 1 })
    local f = font('medium')
    local label = tostring(bt.b[1])
    while #label > 1 and width(f, label) > bt.w - 12 do label = drop_last(label) end
    local tx = bt.x + math.floor((bt.w - width(f, label)) / 2)
    gg:text(tx, bt.y + 15, enabled and label or ('(' .. label .. ')'), { font = f })
  end
end

local function show(m) modal = m; refresh() end
local function close_modal() modal = nil end

-- 成就提示：一次报一个，点掉一个再报下一个，全报完了接着做 after 交代的事。
-- 名字在"成就"那段就挂上了，函数体等到这儿（show 已经声明）才赋值。
flush_ach = function(after)
  if #pending_ach == 0 then if after then after() end; return end
  local ac = pending_ach[1]
  table.remove(pending_ach, 1)
  show({
    title = T('点亮成就 %1 / %2', unlocked_count(), #Data.ACHIEVEMENTS),
    lines = { T('【%1】', ac.name), ac.desc, '成就一次点亮，终身保留，成绩页里能翻。' },
    rows = { { { '好', function() close_modal(); flush_ach(after) end } } },
    cancel = function() close_modal(); flush_ach(after) end,
  })
end

local function info(lines, after)
  if type(lines) == 'string' then lines = { lines } end
  if not lines or #lines == 0 then if after then after() end return end
  show({ lines = lines, rows = { { { '知道了', function() close_modal(); if after then after() end end } } },
    cancel = function() close_modal(); if after then after() end end })
end

-- 数量选择器：1 到 max，按档位加减，四分之一、一半、全部，或者用键盘手输
local function choose_amount(title, max, apply, money, ok_label, note)
  max = math.floor(max or 0)
  if max < 1 then info('现在没什么可做的。'); return end
  local v = max
  local digits = #tostring(max)
  local small = math.max(1, math.floor(10 ^ math.max(0, digits - 2)))
  local big = small * 10
  local m
  local function set(x) v = math.max(1, math.min(max, math.floor(x))); m.lines[2] = money and game:money(v) or fmt(v) end
  m = {
    title = title, lines = { T('最多 %1', money and game:money(max) or fmt(max)), '', note or '' },
    rows = {
      { { '-' .. fmt(big), function() set(v - big) end }, { '-' .. fmt(small), function() set(v - small) end },
        { '+' .. fmt(small), function() set(v + small) end }, { '+' .. fmt(big), function() set(v + big) end } },
      { { '1/4', function() set(max / 4) end }, { '1/2', function() set(max / 2) end },
        { '全部', function() set(max) end }, { '手输', function()
          pcall(function()
            ctx.input:text({ title = title, text = tostring(v) }, function(c, s)
              local n = tonumber((tostring(s or ''):gsub('[^%d]', '')))
              if n then set(n) end
              refresh()
            end)
          end)
        end } },
      { { ok_label or title, function() close_modal(); apply(v); save() end }, { '取消', close_modal } },
    },
    cancel = close_modal,
  }
  set(v)
  show(m)
end

------------------------------------------------------------------ 各个动作

local function trade(i)
  local good = Data.GOODS[i]
  local price = game.prices[i]
  local held = game.inventory[i] or 0
  local basis = game:costBasis(i)
  local lines = { T('现价 %1 · 现金 %2', game:money(price), game:money(game.cash)) }
  -- 基准价和"便宜/贵"只有简单难度才给看
  if show_base() or show_tip() then
    lines[#lines + 1] = T('基准 %1 · %2 · 手上共 %3 件', game:money(good.base), game:tip(i), game:held())
  end
  if held > 0 then
    local pr = game:profit(i)
    local s = T('手上 %1 件，买入价 %2，现值 %3', held, game:money(basis), game:money(held * price))
    lines[#lines + 1] = pr >= 0 and s .. T('，赚 %1', game:money(pr)) or s .. T('，亏 %1', game:money(-pr))
  else
    lines[#lines + 1] = '手上没有这种货。'
  end
  show({
    title = good.name,
    lines = lines,
    rows = {
      { { '买入', function()
          close_modal()
          choose_amount(T('买入 %1', good.name), game:maxBuy(i), function(v)
            local ok, err = game:buy(i, v)
            if ok then status = T('买入 %1 件%2，花了 %3。', v, good.name, game:money(v * game.prices[i]))
            else status = err or '买不了。' end
            check_ach(); flush_ach()
          end, false, '买入', T('现价 %1 · 现金 %2', game:money(game.prices[i]), game:money(game.cash)))
        end, game:maxBuy(i) > 0 },
        { '卖出', function()
          close_modal()
          choose_amount(T('卖出 %1', good.name), held, function(v)
            local p = game.prices[i]
            local ok, err = game:sell(i, v)
            if ok then
              local gain = math.floor(v * (p - basis))
              status = T('卖出 %1 件%2：买入价 %3，现价 %4，到手 %5，%6。', v, good.name,
                game:money(basis), game:money(p), game:money(v * p),
                gain >= 0 and T('赚了 %1', game:money(gain)) or T('亏了 %1', game:money(-gain)))
            else status = err or '卖不了。' end
            check_ach(); flush_ach()
          end, false, '卖出', T('买入价 %1 · 现价 %2', game:money(basis), game:money(game.prices[i])))
        end, held > 0 } },
      { { '取消', close_modal } },
    },
    cancel = close_modal,
  })
end

local over_box

local function next_round()
  close_modal()
  if game.round >= Data.MAX_ROUNDS then end_game(); return end      -- 最后一回合：结束游戏
  local r = game:nextRound()
  save()
  if r.over then over_box(); return end
  -- 特殊事件、小道消息、价格变化，三样分开摆：都该让玩家看见
  local lines = {}
  if #r.events > 0 then
    lines[#lines + 1] = '—— 特殊事件 ——'
    for _k, s in ipairs(r.events) do lines[#lines + 1] = s end
  end
  if r.tip then
    lines[#lines + 1] = '—— 小道消息 ——'
    lines[#lines + 1] = r.tip
  end
  if #r.moves > 0 then
    lines[#lines + 1] = '—— 行情变化 ——'
    for _k, s in ipairs(r.moves) do lines[#lines + 1] = s end
  end
  if #lines == 0 then lines[1] = T('第 %1 回合，行情没什么变化。', game.round) end
  check_ach()
  show({ title = T('第 %1 回合', game.round), lines = lines,
    rows = { { { '知道了', function() close_modal(); flush_ach() end } } },
    cancel = function() close_modal(); flush_ach() end })
end

-- 买房：五个档位，够钱就能点；已经有一套的按原价抵扣，只补差价
local function house_box()
  local lines, rows = {}, {}
  for i, h in ipairs(Data.HOUSES) do
    if i <= game.owned then
      lines[#lines + 1] = T('%1 · %2 · 已拥有', h.name, game:money(h.price))
    else
      local cost = game:houseCost(i)
      local gap = cost - game.cash
      if gap > 0 then
        lines[#lines + 1] = T('%1 · %2 · 还差 %3', h.name, game:money(h.price), game:money(gap))
      elseif game.owned > 0 then
        lines[#lines + 1] = T('%1 · %2 · 补差价 %3 就能换', h.name, game:money(h.price), game:money(cost))
      else
        lines[#lines + 1] = T('%1 · %2 · 现在就能买', h.name, game:money(h.price))
      end
    end
  end
  lines[#lines + 1] = T('现金 %1 · 净资产 %2', game:money(game.cash), game:money(game:netWorth()))
  for i, h in ipairs(Data.HOUSES) do
    rows[#rows + 1] = { { h.name, function()
        close_modal()
        local ok, msg = game:buyHouse(i)
        save()
        if ok then
          record(game:netWorth(), game.owned)
          record_house(i)
          check_ach()
          info({ msg, T('手里还剩 %1。60 个回合还没用完，还能接着换更好的。', game:money(game.cash)) },
            function() flush_ach() end)
        else
          status = msg or '买不了。'
        end
      end, game:canBuyHouse(i) } }
  end
  rows[#rows + 1] = { { '关闭', close_modal } }
  show({ title = '买房：五档，够钱就能买', lines = lines, rows = rows, cancel = close_modal })
end

local function sell_all_box()
  local n, got = 0, 0
  for i = 1, #Data.GOODS do
    local held = game.inventory[i] or 0
    n = n + held
    got = got + held * (game.prices[i] or 0)
  end
  if n == 0 then status = '仓库是空的，没什么可清。'; return end
  show({
    title = '一键清仓',
    lines = { T('把手上 %1 件货全卖掉，到手 %2。', n, game:money(got)) },
    rows = {       { { '清仓', function()
        close_modal()
        local c, g = game:sellAll(); save()
        game:tally()
        status = T('卖出 %1 件，到手 %2。', c, game:money(g))
        check_ach(); flush_ach()
      end }, { '取消', close_modal } } },
    cancel = close_modal,
  })
end

local function market_box()
  local lines = {}
  for i, good in ipairs(Data.GOODS) do
    local p = game.prices[i]
    local prev = game.prev[i] or p
    local mark = p > prev and '▲' or (p < prev and '▼' or '—')
    if show_base() then
      lines[#lines + 1] = T('%1%2 %3（基准 %4）%5', mark, good.name, game:money(p), game:money(good.base), game:tip(i))
    else
      -- 普通难度：只给看得见的事实 —— 现价和比上一回合动了多少
      local d = prev > 0 and math.floor((p - prev) / prev * 100 + 0.5) or 0
      local chg = d == 0 and '与上回合持平' or (d > 0 and T('较上回合 +%1%', d) or T('较上回合 %1%', d))
      lines[#lines + 1] = T('%1%2 %3 · %4', mark, good.name, game:money(p), chg)
    end
    local held = game.inventory[i] or 0
    if held > 0 then lines[#lines] = lines[#lines] .. T(' · 存 %1 件，买入价 %2', held, game:money(game:costBasis(i))) end
  end
  lines[#lines + 1] = '—— 最近的行情 ——'
  for _k, s in ipairs(game.log) do lines[#lines + 1] = s end
  show({ title = T('行情（%1）', diff().name), lines = lines, rows = { { { '关闭', close_modal } } }, cancel = close_modal })
end

-- 彩票站：只有一种玩法，六格刮刮乐

-- 这一张卡刮完了，把六个格子的结果报一遍
local function card_report(total, amounts, extra)
  local parts, blanks = {}, 0
  for _k, a in ipairs(amounts or {}) do
    if a > 0 then parts[#parts + 1] = game:money(a) else blanks = blanks + 1 end
  end
  if blanks > 0 then parts[#parts + 1] = T('笑脸 × %1', blanks) end
  local lines = { T('六个格子：%1', table.concat(parts, ' · ')) }
  if total > 0 then
    local d = total - Data.LOTTERY.price
    lines[#lines + 1] = T('一共刮出 %1', game:money(total))
    lines[#lines + 1] = T('票价 %1，这一张%2', game:money(Data.LOTTERY.price),
      d > 0 and T('赚了 %1', game:money(d)) or (d < 0 and T('亏了 %1', game:money(-d)) or '刚好回本'))
  else
    lines[#lines + 1] = '六格全是笑脸，一张都没刮出来。'
    lines[#lines + 1] = T('票价 %1 就这么没了。', game:money(Data.LOTTERY.price))
  end
  for _k, m in ipairs(extra or {}) do lines[#lines + 1] = m end
  lines[#lines + 1] = T('现金 %1。', game:money(game.cash))
  return lines
end

-- 这三个屏互相串着来：先挂个名字，下面再一个一个定义
local scratch_box, scratch_all, cash_in

-- 六个格子全刮开之后：把卡交回站里，钱入账
cash_in = function()
  local total, amounts, extra = game:cashCard()
  save()
  if total == nil then lottery_box(); return end
  check_ach()
  info(card_report(total, amounts, extra), function() flush_ach(lottery_box) end)
end

-- 卡上还有没刮开的：一把全刮了，省得一个个点
scratch_all = function()
  for k = 1, Data.LOTTERY.cells do game:scratchCell(k) end
  save()
  scratch_box()
end

-- 刮刮卡这一屏：六个盖着涂层的格子，点一格开一格；全刮完了自己按收下
scratch_box = function()
  local amounts, open = game:lotteryCard()
  if not amounts then lottery_box(); return end
  local cells = {}
  for k = 1, #amounts do
    cells[k] = { amount = amounts[k], open = open[k], fn = function()
        game:scratchCell(k)
        save()
        check_ach()                       -- 只记着，等这一张刮完再一起报，不打断刮卡
        scratch_box()
      end }
  end
  local n = game:cardOpenCount()
  local lines = {
    T('已经刮开 %1 / %2 格，到手 %3。', n, #amounts, game:money(game:cardRevealedTotal())),
  }
  if n == 0 then lines[#lines + 1] = T('点一个格子刮一下。票价 %1。', game:money(Data.LOTTERY.price)) end
  local rows = {}
  if game:cardDone() then
    rows[#rows + 1] = { { '收下这笔钱', cash_in } }
  else
    rows[#rows + 1] = { { '剩下的全刮开', scratch_all } }
  end
  rows[#rows + 1] = { { '关闭', close_modal } }
  show({
    title = T('刮刮乐 · 第 %1 张', game.lotto_n or 1),
    lines = lines, cells = cells, rows = rows,
    cancel = close_modal,
  })
end

lottery_box = function()
  local L = Data.LOTTERY
  local holding = game:lotteryCard() ~= nil
  local can = select(1, game:canLottery())
  -- 六个格子各自的金额：给玩家看看这一张最多能刮出什么
  local tops = {}
  for _k, p in ipairs(L.CELL_PRIZES) do if p.amount > 0 then tops[#tops + 1] = p.amount end end
  table.sort(tops, function(a, b) return a > b end)
  local lines = {
    T('%1 一张 · 六个格子 · 还剩 %2 张', game:money(L.price), game:lotteryLeft()),
    '一格一格点开，刮出金额就攒着',
    '是笑脸就是没中，六格加起来算总账',
    T('一格最多 %1 · 奖池 %2', game:money(tops[1] or 0), game:money(game:lotteryPool())),
    T('每张票 1/%1 的机会独得奖池', L.pool_chance),
    T('本局 %1 张 · 花 %2 · 中 %3', game.lotto_n or 0, game:money(game.lotto_spent or 0), game:money(game.lotto_win or 0)),
  }
  if game:lotteryFree() > 0 then lines[#lines + 1] = T('手上还有 %1 张白得的券。', game:lotteryFree()) end
  if holding then lines[#lines + 1] = '手上那张还没刮完。' end
  show({
    title = '彩票站',
    lines = lines,
    rows = {
      { { holding and '接着刮' or T('买一张（%1）', game:money(L.price)), function()
          close_modal()
          if holding then scratch_box(); return end
          local ok, err = game:buyLottery()
          if ok then
            save()
            tot.cards = (tot.cards or 0) + 1        -- 跨局累计刮了几张，成就"刮刮乐常客"看它
            save_best()
            check_ach()
            scratch_box()
          else status = err or '买不了。' end
        end, holding or can } },
      { { '关闭', close_modal } },
    },
    cancel = close_modal,
  })
end

-- 难度：只改看得见多少信息，不影响钱和价格
difficulty_box = function()
  local lines, rows = {}, {}
  for i, d in ipairs(Data.DIFFICULTY) do
    lines[#lines + 1] = (i == difficulty and '▸ ' or '') .. d.name .. '：' .. d.desc
    rows[#rows + 1] = { { i == difficulty and T('%1（当前）', d.name) or d.name, function()
        close_modal()
        difficulty = i
        save_settings()
        status = T('难度：%1。%2', d.name, d.desc)
      end, i ~= difficulty } }
  end
  rows[#rows + 1] = { { '关闭', close_modal } }
  show({ title = '难度：只改显示多少信息', lines = lines, rows = rows, cancel = close_modal })
end

-- 小道消息：花点钱买句话，说的是某样货接下来几个回合要涨还是要跌。
-- 七成靠得住（价格真会往说的方向走），三成是坑（反着走），还有一成是废话。
local function tip_box()
  local Tp = Data.TIPS
  local lines = {
    T('%1 一条 · 这回合还剩 %2 条', game:money(Tp.price), game:tipLeft()),
    '说的是接下来几个回合的涨跌。',
  }
  local held, span = game:tipText(), game:tipSpan()
  if held and span > 0 then
    lines[#lines + 1] = '—— 手上这条 ——'
    lines[#lines + 1] = held
    lines[#lines + 1] = T('还有 %1 个回合见分晓。', span)
    lines[#lines + 1] = game.tip_dir and (game.tip_dir > 0 and '要涨就先囤着。' or '要跌就赶紧抛。') or ''
  else
    lines[#lines + 1] = '手上没有消息。'
  end
  lines[#lines + 1] = T('这一局买过 %1 条，应验 %2 条。',
    (game.stat and game.stat.tips) or 0, (game.stat and game.stat.tip_true) or 0)
  lines[#lines + 1] = T('历来一共买过 %1 条。', tot.tips or 0)
  local can = game:tipLeft() > 0 and span <= 0 and game.cash >= Tp.price and not game.over
  show({
    title = '小道消息',
    lines = lines,
    rows = {
      { { T('买一条（%1）', game:money(Tp.price)), function()
          close_modal()
          local text, err = game:buyTip()
          if not text then status = err or '买不了。'; return end
          save()
          tot.tips = (tot.tips or 0) + 1
          save_best()
          check_ach()
          -- 先把消息摆出来看，看完再报成就
          local tail
          if game.tip_junk then tail = '（这句什么也没说，钱白花了。）'
          elseif game.tip_dir > 0 then tail = T('要涨：先囤着，%1 个回合后卖。', game:tipSpan())
          else tail = T('要跌：手上有的先抛，%1 个回合后再买回来。', game:tipSpan()) end
          show({
            title = '买到了一句话',
            lines = { text, tail, T('现金还剩 %1。', game:money(game.cash)) },
            rows = { { { '好', function() close_modal(); flush_ach() end } } },
            cancel = function() close_modal(); flush_ach() end,
          })
        end, can } },
      { { '关闭', close_modal } },
    },
    cancel = close_modal,
  })
end

-- 成就墙：十四个成就一屏摆不下，摆三页，翻着看。
-- ★ 是点亮过的，☆ 是还没拿到的（条件也摆出来，才知道往哪儿奔）。
local ACH_PER_PAGE = 5
local ach_page = 1

local function ach_wall(page)
  local n = #Data.ACHIEVEMENTS
  local npages = math.ceil(n / ACH_PER_PAGE)
  ach_page = math.max(1, math.min(page or 1, npages))
  local a = (ach_page - 1) * ACH_PER_PAGE + 1
  local b = math.min(n, a + ACH_PER_PAGE - 1)
  local lines = {}
  for i = a, b do
    local ac = Data.ACHIEVEMENTS[i]
    lines[#lines + 1] = (unlocked[ac.id] and '★ ' or '☆ ') .. ac.name
    lines[#lines + 1] = '    ' .. ac.desc
  end
  show({
    title = T('成就墙 %1/%2 页 · 点亮 %3 个', ach_page, npages, unlocked_count()),
    lines = lines,
    rows = {
      { { '上一页', function() close_modal(); ach_wall(ach_page - 1) end, ach_page > 1 },
        { '下一页', function() close_modal(); ach_wall(ach_page + 1) end, ach_page < npages } },
      { { '关闭', close_modal } },
    },
    cancel = close_modal,
  })
end

-- 历史成绩：只放钱和房子，成就另开一页（挤在一起两边都看不清）
local function scores_box()
  local h = best_house > 0 and Data.HOUSES[best_house].name or '一套都没买过'
  local lines = {
    T('最高净资产：%1', game:money(best_net)),
    T('买到过最好的房子：%1（%2）', h, best_house > 0 and Data.HOUSES[best_house].rank or Data.NO_HOUSE_RANK),
    '—— 各房型买到过几次 ——',
  }
  -- 每一档历年一共买到过几次（往上换房时每一档各记一次）
  for i, hh in ipairs(Data.HOUSES) do
    lines[#lines + 1] = T('%1 · %2 · %3 次', hh.name, game:money(hh.price), math.floor(house_wins[i] or 0))
  end
  lines[#lines + 1] = T('历年一共买到 %1 次。', total_house_wins())
  lines[#lines + 1] = '往上换房时，每一档各记一次。'
  lines[#lines + 1] = T('成就点亮 %1 / %2，点“成就墙”翻。', unlocked_count(), #Data.ACHIEVEMENTS)
  show({
    title = '历史成绩',
    lines = lines,
    rows = { { { '成就墙', function() close_modal(); ach_wall(1) end }, { '关闭', close_modal } } },
    cancel = close_modal,
  })
end

local function new_game_box()
  show({
    title = '重新开始？现在这一局就没了。',
    rows = { { { '新游戏', function() close_modal(); game:newGame(); save(); status = '新的一局：2000 元，60 个回合。' end },
               { '取消', close_modal } } },
    cancel = close_modal,
  })
end

local function finish_game()
  game:finish()
  save()
  over_box()
end

-- 最后一回合点"结束游戏"：还没买房、而钱又够，先问一句要不要先买
end_game = function()
  close_modal()
  if game.over then over_box(); return end
  if game.owned <= 0 then
    local best_i = nil                                  -- 现金买得起的最高一档
    for i = #Data.HOUSES, 1, -1 do if game:canBuyHouse(i) then best_i = i; break end end
    if best_i then
      local h = Data.HOUSES[best_i]
      show({
        title = '这是最后一回合了',
        lines = { T('手上还有 %1，够买%2（%3）。', game:money(game.cash), h.name, game:money(h.price)),
          '结束之后这一局就定格了，房子就买不成了。' },
        rows = { { { '先买房', function() close_modal(); house_box() end },
                   { '直接结束', function() close_modal(); finish_game() end } } },
        cancel = close_modal,
      })
      return
    end
    local after = game.cash + game:stockValue()           -- 清仓之后能凑到多少
    if game:held() > 0 and after >= Data.HOUSES[1].price then
      show({
        title = '这是最后一回合了',
        lines = { T('现金只有 %1，但把手上 %2 件货清掉能有 %3，够买%4。', game:money(game.cash),
            game:held(), game:money(after), Data.HOUSES[1].name),
          '结束之后这一局就定格了，房子就买不成了。' },
        rows = { { { '先清仓', function() close_modal(); game:sellAll(); save(); end_game() end },
                   { '直接结束', function() close_modal(); finish_game() end } } },
        cancel = close_modal,
      })
      return
    end
  end
  finish_game()
end

over_box = function()
  -- 收摊时手上还捏着没刮完的卡：已经刮出来的那几格还是算数，剩下的归站里
  local card_got = 0
  if game:lotteryCard() then
    local t = game:cashCard()
    card_got = t or 0
    save()
  end
  local net = game:netWorth()
  record(net, game.owned)
  local house = game.owned > 0 and Data.HOUSES[game.owned].name or '没买到房'
  local lines = {
    T('净资产：%1', game:money(net)),
    T('房产：%1 · %2', house, game:rank()),
    T('历史最好：%1', game:money(best_net)),
    game.owned > 0 and T('%1 个回合里，你从 %2 做到了有房的人。', game.round, game:money(Data.START_CASH))
      or T('%1 个回合过去了，房子还是别人的。再来一局？', game.round),
  }
  if card_got > 0 then
    lines[#lines + 1] = T('手上那张刮刮乐刮出 %1。', game:money(card_got))
  end
  check_ach()
  -- 有成就刚点亮就先报一声，报完再摆结算页
  flush_ach(function()
    show({ title = '六十回合结束', lines = lines,
      rows = { { { '新游戏', function() close_modal(); game:newGame(); save() end } } } })
  end)
end

------------------------------------------------------------------ 那一屏

local MARKET_Y, ROW, BTN_Y, BTN_H, BTN_GAP = 104, 57, 566, 52, 10

-- 最后一回合：那颗按钮不再说"下一回合"，而是"结束游戏"
local function next_label()
  return game.round >= Data.MAX_ROUNDS and '结束游戏' or '下一回合'
end

-- 底部三行按钮：每行里的按钮平分整行宽度
local function button_rows()
  return {
    { { next_label(), next_round }, { '买房', house_box }, { '彩票', function() lottery_box() end } },
    { { '一键清仓', sell_all_box }, { '行情', market_box }, { '难度', function() difficulty_box() end } },
    { { '新游戏', new_game_box }, { '小道消息', tip_box }, { '成绩', scores_box } },
  }
end
local function button_rects()
  local out, y = {}, BTN_Y
  for _r, row in ipairs(button_rows()) do
    local n = #row
    local bw = math.floor((W - 16 - (n - 1) * 8) / n)
    for k, btn in ipairs(row) do
      out[#out + 1] = { x = 8 + (k - 1) * (bw + 8), y = y, w = bw, h = BTN_H, b = btn }
    end
    y = y + BTN_H + BTN_GAP
  end
  return out
end

local function draw_board(gg, top_only)
  gg:text(16, 10, short(T('现金 %1', game:money(game.cash)), 30), { font = font('large') })
  local round = T('第 %1 / %2 回合', game.round, Data.MAX_ROUNDS)
  gg:text(W - 16 - width(font('medium'), round), 14, round, { font = font('medium') })
  gg:text(16, 48, short(T('净资产 %1 · 持仓 %2 件', game:money(game:netWorth()), game:held()), 52), { font = font('small') })
  local house = game.owned > 0 and T('房产 %1（%2）', Data.HOUSES[game.owned].name, game:money(game:houseValue())) or T('房产 无 · %1', Data.NO_HOUSE_RANK)
  gg:text(16, 72, short(house, 52), { font = font('small') })
  gg:line(0, 96, W, 96)
  if top_only then return end        -- 弹窗开着：剩下的屏幕归它
  for i, good in ipairs(Data.GOODS) do
    local y = MARKET_Y + (i - 1) * ROW
    local p = game.prices[i]
    local prev = game.prev[i] or p
    local mark = p > prev and '▲' or (p < prev and '▼' or '—')
    local ps = mark .. ' ' .. game:money(p)
    gg:text(16, y + 2, short(good.name, 16), { font = font('medium') })
    gg:text(W - 16 - width(font('medium'), ps), y + 2, ps, { font = font('medium') })
    local held = game.inventory[i] or 0
    local sub
    if held > 0 then
      -- 自己的账本：买入价和赚亏两个难度都给看
      sub = T('存 %1 件 · 本 %2 · 值 %3', held, game:money(game:costBasis(i)), game:money(held * p))
      local pr = game:profit(i)
      if pr > 0 then sub = sub .. T(' · 赚 %1', game:money(pr))
      elseif pr < 0 then sub = sub .. T(' · 亏 %1', game:money(-pr)) end
    elseif show_base() then
      sub = T('基准 %1 · %2', game:money(good.base), game:tip(i))
    else
      local d = prev > 0 and math.floor((p - prev) / prev * 100 + 0.5) or 0
      sub = d == 0 and '与上回合持平' or (d > 0 and T('较上回合 +%1%', d) or T('较上回合 %1%', d))
    end
    gg:text(16, y + 28, short(sub, 52), { font = font('small') })
    gg:line(16, y + 50, W - 16, y + 50)
  end
  for _k, bt in ipairs(button_rects()) do
    gg:rect(bt.x, bt.y, bt.w, bt.h)
    local f = font('small')
    local label = tostring(bt.b[1])
    while #label > 1 and width(f, label) > bt.w - 10 do label = drop_last(label) end
    gg:text(bt.x + math.floor((bt.w - width(f, label)) / 2), bt.y + 16, label, { font = f })
  end
  -- 底下两行给状态：卖出后那句"买入价多少、现价多少"一句话写不下，拆两行
  -- 手上揣着消息的时候，先提醒一句（它管着好几个回合，容易忘）
  local tip_hint = nil
  if game:tipSpan() > 0 and game.tip_idx and game.tip_idx > 0 then
    local g = Data.GOODS[game.tip_idx]
    tip_hint = T('消息：%1还要%2 %3 个回合。', g and g.name or '行情',
      game.tip_dir and game.tip_dir > 0 and '涨' or '跌', game:tipSpan())
  end
  local hint = status ~= '' and status
    or (game.round >= Data.MAX_ROUNDS and '最后一回合了：点“结束游戏”收摊。')
    or tip_hint
    or '点商品买卖，点“下一回合”进入下一回合。'
  local sl = wrap(hint, 'small', W - 32)
  gg:text(16, H - 46, short(sl[1] or '', 60), { font = font('small') })
  if ERR then gg:text(16, H - 24, short('ERR ' .. ERR, 52), { font = font('small') })
  elseif sl[2] and sl[2] ~= '' then gg:text(16, H - 24, short(sl[2], 60), { font = font('small') }) end
end

function on_draw(c, gg)
  if not gg then return end
  local ok, e = pcall(function()
    gg:clear(0)
    draw_board(gg, modal ~= nil)
    if modal then draw_modal(gg) end
  end)
  if not ok then pcall(function() gg:text(8, H - 70, short('draw ERR ' .. tostring(e), 46)) end) end
end

local KEY_GAP_MS = 250
local last_key, last_key_ms = nil, nil
local function key_accepted(ev)
  local ph = ev.phase or ev.action or ev.state
  if ph == 'up' or ph == 'release' or ph == 'released' or ev.pressed == false or ev.down == false then return false end
  local now = tonumber(ev.time_ms)
  if not now then local ok, m = pcall(function() return ctx.clock:millis() end); now = ok and tonumber(m) or nil end
  if now and last_key == ev.key and last_key_ms and now - last_key_ms >= 0 and now - last_key_ms < KEY_GAP_MS then return false end
  last_key, last_key_ms = ev.key, now
  return true
end

local function tap(x, y)
  if modal then
    local _l, btns, my, mh, cells = layout_modal(modal)
    for _k, cl in ipairs(cells) do
      if x >= cl.x and x < cl.x + cl.w and y >= cl.y and y < cl.y + cl.h then
        if cl.c.fn then cl.c.fn() end
        return
      end
    end
    for _k, bt in ipairs(btns) do
      if x >= bt.x and x < bt.x + bt.w and y >= bt.y and y < bt.y + bt.h then
        if bt.b[3] ~= false then bt.b[2]() end
        return
      end
    end
    if (y < my or y > my + mh or x < BOX_X or x > BOX_X + BOX_W) and modal.cancel then modal.cancel() end
    return
  end
  status = ''
  for _k, bt in ipairs(button_rects()) do
    if x >= bt.x and x < bt.x + bt.w and y >= bt.y and y < bt.y + bt.h then bt.b[2](); return end
  end
  if y >= MARKET_Y and y < MARKET_Y + #Data.GOODS * ROW then trade(math.floor((y - MARKET_Y) / ROW) + 1) end
end

-- 返回键：弹窗开着就先关弹窗；没有弹窗就**不认领**这个事件，交回系统，让系统弹"离开应用"。
-- on_input 返回 true 是"这个事件归我"，系统就再也看不到了 —— 以前无条件返回 true，
-- 返回键被吃掉，所以怎么按都退不出去。
function on_input(c, ev)
  ERR = nil
  local back_to_system = false
  local ok, e = pcall(function()
    if type(ev) ~= 'table' then return end
    if ev.type == 'pointer' and ev.phase == 'up' then
      tap(ev.x or 0, ev.y or 0)
    elseif ev.type == 'key' and ev.key == 'back' then
      if modal and modal.cancel then
        if key_accepted(ev) then modal.cancel() end
      else
        back_to_system = true       -- 交给系统：弹出"离开应用"
      end
    end
  end)
  if not ok then ERR = tostring(e) end
  if back_to_system then save() end
  refresh()
  return not back_to_system
end

function on_load(c)
  load_best()
  load_settings()
  game = Game:new()
  if not load_saved() then game:newGame(); save() end
  if game.over then over_box(); return end
  -- 上一回退出时卡上还有没刮完的，进来就提醒一下
  if game:lotteryCard() then
    status = T('手上那张刮刮乐还剩 %1 格没刮。', Data.LOTTERY.cells - game:cardOpenCount())
  end
end

function on_leave() save() end
